#include <iostream>

using std::cout;
using std::cin;
using std::endl;

int main()
{
    int iScore;

    cout << "점수를 입력하세요(0~100): ";
    cin >> iScore;

    if (iScore < 0 || 100 < iScore)
    {
        cout << "잘못된 점수입니다." << endl;
    }
    else if (90 <= iScore && iScore <= 100)
    {
        cout << "A" << endl;

        if (100 == iScore)
        {
            cout << "만점입니다!" << endl;
        }
    }
    else if (80 <= iScore && iScore <= 89)
    {
        cout << "B" << endl;
    }
    else if (70 <= iScore && iScore <= 79)
    {
        cout << "C" << endl;
    }
    else
    {
        cout << "F" << endl;
    }

    return 0;
}

