#include <iostream>

using std::cout;
using std::cin;
using std::endl;

int main()
{
    const int iStrength  = 0x00000001;
    const int iDefense   = 0x00000002;
    const int iSpeed     = 0x00000004;
    const int iParalysis = 0x00000008;
    const int iPoisoning = 0x00000010;

    int iBuff;

    cout << "버프 상태를 입력하세요: ";
    cin >> iBuff;

    if (iBuff & iStrength)
        cout << "Strength 버프가 존재합니다." << endl;

    if (iBuff & iDefense)
        cout << "Defense 버프가 존재합니다." << endl;

    if (iBuff & iSpeed)
        cout << "Speed 버프가 존재합니다." << endl;

    if (iBuff & iParalysis)
        cout << "Paralysis 버프가 존재합니다." << endl;

    if (iBuff & iPoisoning)
        cout << "Poisoning 버프가 존재합니다." << endl;

    if (iBuff & iParalysis)
    {
        cout << "상태이상: Paralysis 상태입니다." << endl;
    }
    else if (iBuff & iPoisoning)
    {
        cout << "상태이상: Poisoning 상태입니다." << endl;
    }
    else
    {
        cout << "상태이상이 없습니다." << endl;
    }

    return 0;
}
